/* Shared visual refresh and responsive layout corrections. */
:root {
  --app-font: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --bs-font-sans-serif: var(--app-font);
  --app-background: #eaf0f8;
  --banner-height: 0px;
  --header-height: 60px;
}

body, .content-wrapper, .footer {
  background: var(--app-background);
}

body, h1, h2, h3, h4, h5, h6, .h1, .h2, .h3, .h4, .h5, .h6,
button, input, select, textarea, .form-control, .btn, .footer {
  font-family: var(--app-font);
}

.card {
  border: 1px solid #dce4f0;
  border-radius: 12px;
  box-shadow: 0 4px 18px rgba(35, 55, 85, .04);
  min-width: 0;
}

.main-panel, .content-wrapper, .card-body, .row > * {
  min-width: 0;
}

.sidebar { flex-shrink: 0; }

.navbar.fixed-top { top: var(--banner-height); flex-wrap: nowrap; }
.page-body-wrapper:not(.full-page-wrapper) {
  padding-top: calc(var(--banner-height) + var(--header-height));
}

#proBanner { background: #233653; }
#proBanner .card-body-padding { gap: 16px; }
#proBanner .card-body-padding > :first-child { min-width: 0; }
#proBanner .card-body-padding > :last-child,
#proBanner .buy-now-btn { flex-shrink: 0; }

.navbar .navbar-menu-wrapper { min-width: 0; gap: 16px; }
.navbar .navbar-menu-wrapper > .navbar-nav:first-child { min-width: 0; flex: 1; }
.navbar .navbar-menu-wrapper .navbar-nav-right { flex-shrink: 0; }
.navbar .navbar-menu-wrapper .nav-search .input-group { flex-wrap: nowrap; align-items: center; }
.navbar .navbar-menu-wrapper .nav-search .form-control { min-width: 0; }

.content-wrapper > .row:first-child .d-flex.flex-wrap { gap: 16px; }
.dashboard-tabs .tab-pane > .d-flex { gap: 8px 0; }
.dashboard-tabs .item { flex: 1 1 170px; min-width: 0; }
.dashboard-chart-legend { display: flex; flex-wrap: wrap; gap: 10px 20px; }
.dashboard-chart-legend li { display: inline-flex; align-items: center; }
.dashboard-chart-legend li:not(:first-child) span { margin-left: 0; }
.table-responsive { max-width: 100%; }

@media (max-width: 991px) {
  .sidebar-offcanvas {
    top: calc(var(--banner-height) + var(--header-height));
    max-height: calc(100vh - var(--banner-height) - var(--header-height));
  }
  .navbar .navbar-brand-wrapper { flex-shrink: 0; }
  .navbar .navbar-brand-wrapper .navbar-brand-inner-wrapper { margin: 0; justify-content: center !important; }
  .navbar .navbar-brand-wrapper [data-toggle="minimize"] { display: none; }
  .navbar .navbar-menu-wrapper > .navbar-nav:first-child { display: none !important; }
  .navbar .navbar-menu-wrapper .navbar-nav .nav-item { margin-left: 8px; margin-right: 8px; }
}

@media (max-width: 767px) {
  .content-wrapper { padding: 24px 16px; }
  .card .card-body { padding: 20px; }
  .navbar .navbar-menu-wrapper { gap: 4px; padding: 0 8px; }
  .navbar .navbar-menu-wrapper .navbar-nav .nav-item.dropdown .navbar-dropdown {
    top: calc(var(--banner-height) + var(--header-height));
    max-height: calc(100vh - var(--banner-height) - var(--header-height) - 16px);
    overflow-y: auto;
  }
  #proBanner .card-body-padding > :first-child > .d-flex { flex-wrap: wrap; gap: 0 12px; }
  #proBanner .buy-now-text { font-size: 12px; }
  #proBanner .btn.buy-now-btn { min-width: 0; padding: 6px 0; }
  .dashboard-tabs .item { flex-basis: 50%; justify-content: flex-start !important; }
  .dashboard-tabs .item .icon-lg { font-size: 28px; margin-right: 8px !important; }
  .footer { display: flex; flex-wrap: wrap; gap: 8px 16px; line-height: 1.6; }
}

@media (max-width: 359px) {
  .dashboard-tabs .item { flex-basis: 100%; }
}

