    var banner = document.querySelector('#proBanner');
    var bannerClose = document.querySelector('#bannerClose');

    // Measure wrapped banner text instead of assuming a fixed banner height.
    function updateHeaderSpacing() {
      var height = banner ? banner.getBoundingClientRect().height : 0;
      document.documentElement.style.setProperty('--banner-height', height + 'px');
    }

    if (banner) {
      var dismissed = $.cookie && $.cookie('majestic-free-banner') === 'true';
      banner.classList.toggle('d-none', !!dismissed);
      banner.classList.toggle('d-flex', !dismissed);
      if (window.ResizeObserver) {
        new ResizeObserver(updateHeaderSpacing).observe(banner);
      }
    }
    updateHeaderSpacing();
